import{z as A,x as B,o as r,c as d,q as o,j as l,D as t,d as s,s as E,S as i,b as e}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"写穿与写周围","description":"","frontmatter":{"title":"写穿与写周围","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/write-through.md","filePath":"cs/write-through.md","lastUpdated":1791063341000}'),p={name:"cs/write-through.md"};function c(h,a,D,m,C,u){const n=B("Mermaid");return r(),d("div",null,[a[2]||(a[2]=o('<h1 id="写穿与写周围" tabindex="-1">写穿与写周围 <a class="header-anchor" href="#写穿与写周围" aria-label="Permalink to &quot;写穿与写周围&quot;">​</a></h1><div class="epigraph"><p>每次写都推到下一层，层次之间不长期分叉；写缺失若绕过 cache，一次性存储就不会把有用块挤掉。</p><footer>—— 据 Patterson and Hennessy, Computer Organization and Design (RISC-V)；Hennessy and Patterson, CA:AQA 整理</footer></div><p><a href="/cs/write-back-allocate">上一课</a>把写回加写分配钉成后课默认，并点名写直达与不分配常成对。本课不重讲脏位。缺口是把另一对策略写清楚：写穿（写直达）如何用写缓冲躲开 DRAM 延迟，以及写周围（不分配）何时避免污染。本课是对照，不推翻默认。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>写回让 SRAM 比 DRAM 新，单核看不见，DMA 与多核立刻看见。<a href="/cs/coherence-intro">一致性问题引入</a>还在后面。有的层次——尤其指令 cache 旁的数据写入、或极简嵌入式核——宁愿<strong>每次 store 都更新下一层</strong>，省掉脏位与写回事务。写缺失若仍分配，一块只写一次的轨迹会踢掉热块。缺口不是再定义标签，而是写穿路径与写周围规则。</p><p><span class="marginnote">术语翻译：写周围（写不分配）就是「这块就不请进 cache 了」——缺失的 store 直接写给下一层，cache 不留位置。省下的是把整块读进来的一次分配；赌的是这个字节之后不再被读。</span></p><p><span class="marginnote">写周围 = 写不分配：缺失的 store 直接去下一层，cache 不填块。读缺失仍分配。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>写穿：写命中时同时写 SRAM 与下一层（或只保证下一层会得到该字）。脏位可省。CPU 等 DRAM 完成则 CPI 崩；中间加写缓冲：store 把地址与数据放入队列即可提交，缓冲自己排到总线。</p><p><span class="marginnote">数字实例：一次 DRAM 写要等约 100 拍才完成；有写缓冲时 CPU 把地址和数据排进队列就继续跑，写延迟被藏在后台。没有缓冲的裸写穿，写密集循环的 CPI 直接被钉在内存延迟上。</span></p><p>写周围：写缺失不填 cache。适合「写一次、不再读」的流。若随后马上读同一块，会再付一次读缺失——与写分配的交易。</p>',11)),(r(),l(i,null,{default:t(()=>[E(n,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20WH%5B%22%E5%86%99%E5%91%BD%E4%B8%AD%22%5D%20--%3E%20WT%5B%22%E5%86%99%E7%A9%BF%EF%BC%9ASRAM%20%E4%B8%8E%E4%B8%8B%E4%B8%80%E5%B1%82%22%5D%0A%20%20WT%20--%3E%20BUF%5B%22%E5%86%99%E7%BC%93%E5%86%B2%E8%A7%A3%E8%80%A6%20CPU%22%5D%0A%20%20WM%5B%22%E5%86%99%E7%BC%BA%E5%A4%B1%22%5D%20--%3E%20WA%5B%22%E5%86%99%E5%88%86%E9%85%8D%EF%BC%9A%E5%A1%AB%E5%9D%97%22%5D%0A%20%20WM%20--%3E%20NAR%5B%22%E5%86%99%E5%91%A8%E5%9B%B4%EF%BC%9A%E7%BB%95%E8%BF%87%20cache%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"后续 load 必须探测写缓冲：命中则转发，否则可能读到旧 DRAM。上一课承认缓冲存在；本课把它当成写穿能用的前提。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[s("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"写穿的流量按 store 次数计，写回按脏块驱逐计。写密集且每块只写一字节时，写穿更差；块上多次写再驱逐时，写回合并。指令 cache 通常只读，不参与这套；I/D 分离后，数据写穿仍可能要作废指令行——一致性课再收。",-1)),a[6]||(a[6]=e("p",null,"load 为什么要先探测写缓冲：",-1)),(r(),l(i,null,{default:t(()=>[E(n,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20L%5B%22load%20%E5%8F%91%E5%87%BA%22%5D%20--%3E%20Q%7B%22%E5%9C%B0%E5%9D%80%E5%9C%A8%E5%86%99%E7%BC%93%E5%86%B2%E9%87%8C%E5%90%97%22%7D%0A%20%20Q%20--%3E%7C%22%E5%91%BD%E4%B8%AD%22%7C%20FWD%5B%22%E7%BC%93%E5%86%B2%E8%BD%AC%E5%8F%91%E6%9C%80%E6%96%B0%E6%95%B0%E6%8D%AE%22%5D%0A%20%20Q%20--%3E%7C%22%E6%9C%AA%E5%91%BD%E4%B8%AD%22%7C%20RD%5B%22%E7%85%A7%E5%B8%B8%E8%AF%BB%20cache%20%E6%88%96%20DRAM%22%5D%0A%20%20FWD%20--%3E%20OK%5B%22%E4%B8%8D%E4%BC%9A%E8%AF%BB%E5%88%B0%E6%97%A7%20DRAM%22%5D%0A%20%20RD%20--%3E%20OK%0A"})]),fallback:t(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<p>简单多核：写穿让下一层（或总线）总有最新字，窥探可只听写事务。这不代替 MESI，只是协议可以更瘦。主干数据 cache 仍默认写回。</p><p><span class="marginnote">常见误区：以为 store 进了写缓冲就算「完成」。对下一层而言确实迟早会到，但对紧跟着的 load 而言，缓冲里那份才是最新的——不先探测缓冲，程序就会读到 DRAM 上的旧值。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 MSHR，不把写结合（write combining）当成第三种主策略——它是缓冲上的合并优化。也不把页的脏位与 cache 写穿混名。后课缺失分类把写缺失计入轨迹时，须声明用的是分配还是周围。</p><p>后课默认：数据 cache 仍是写回加写分配；写穿加写周围作为对照与写缓冲注脚。谈到缺失，按三类拆。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>写穿每 store 更新下一层，靠写缓冲藏延迟；可省脏位。</li><li>写周围在写缺失时不填块，避免一次性写污染。</li><li>主干默认仍是写回；缺失分类是下一课。</li><li>出处：Patterson and Hennessy, <em>COD</em> RISC-V；Hennessy and Patterson, <em>CA:AQA</em>。</li></ul>',7))])}const P=A(p,[["render",c]]);export{_ as __pageData,P as default};
